    'hard',
    'A company''s cash book shows a bank balance of ₹25,000 (Dr.). Cheques amounting to ₹5,000 were issued but not presented. Cheques deposited but not cleared amounted to ₹3,000. Bank charges of ₹200 were not recorded in the cash book. What is the balance as per pass book?',
