    0,
    'Original Cost (April 1, 2020) = ₹1,50,000.
Depreciation for FY 2020-21 (April 1, 2020 to March 31, 2021 = 12 months): ₹1,50,000 * 10% = ₹15,000.
WDV on April 1, 2021 = ₹1,50,000 - ₹15,000 = ₹1,35,000.
Depreciation for FY 2021-22 (April 1, 2021 to March 31, 2022 = 12 months): ₹1,35,000 * 10% = ₹13,500.
WDV on April 1, 2022 = ₹1,35,000 - ₹13,500 = ₹1,21,500.
Depreciation for 6 months (April 1, 2022 to Sept 30, 2022): ₹1,21,500 * 10% * (6/12) = ₹6,075.
Book Value on Sept 30, 2022 = ₹1,21,500 - ₹6,075 = ₹1,15,425.
Selling Price = ₹1,10,000.
Loss on Sale = Book Value - Selling Price = ₹1,15,425 - ₹1,10,000 = ₹5,425.',
