    'Cash Flow Statement',
    'operating_activities_indirect_method',
    'medium',
    'If a company''s net profit is ₹2,00,000. During the year, it had a loss on sale of machinery of ₹30,000 and an increase in prepaid expenses of ₹10,000. What is the cash flow from operating activities before working capital changes?',
