    'Starting with net profit of ₹2,00,000, add back the loss on sale of machinery (₹30,000) as it''s a non-cash expense that reduced profit. An increase in prepaid expenses is a use of cash, so it''s subtracted when calculating cash flow from operations. However, the question asks for cash flow *before* working capital changes, so we only adjust for the non-cash loss. Thus, ₹2,00,000 + ₹30,000 = ₹2,30,000.',
    'seed_rbse_commerce_deepen_accountancy_v1',
