    'Amortization of intangible assets like goodwill is treated similarly to depreciation in a cash flow statement prepared using the indirect method because:',
    '["It is a cash outflow from operating activities.","It is a cash inflow from investing activities.","It is a non-cash expense that reduces net profit.","It is added back to net profit as it relates to financing."]'::jsonb,
