    'hard',
    'A company reported a net profit of ₹5,00,000. During the year, it wrote off bad debts of ₹20,000 and made a provision for doubtful debts of ₹30,000. The opening provision was ₹15,000. What is the adjustment for bad debts and provision for doubtful debts in the calculation of cash flow from operating activities?',
    '["Add ₹20,000, Add ₹15,000","Add ₹20,000, Subtract ₹30,000","Add ₹20,000, Add ₹15,000 (net increase)","Add ₹20,000, Subtract ₹15,000 (net increase)"]'::jsonb,
    2,
    'The bad debts written off (₹20,000) are a non-cash expense that reduced profit, so they are added back. The net increase in provision for doubtful debts is ₹30,000 (closing) - ₹15,000 (opening) = ₹15,000. This increase represents an estimated future loss and is treated as an addition to net profit because it''s a non-cash charge. So, add ₹20,000 (bad debts) and add ₹15,000 (net increase in provision).',
    'seed_rbse_commerce_deepen_accountancy_v1',
