    12,
    'Accountancy',
    'Cash Flow Statement',
    'investing_activities',
    'hard',
    'A company sold a piece of land for ₹5,00,000 and purchased new machinery for ₹8,00,000. It also received ₹1,00,000 as dividend from its investment in shares. What is the net cash flow from investing activities?',
    '["₹(2,00,000)","₹(3,00,000)","₹(4,00,000)","₹(1,00,000)"]'::jsonb,
    0,
    'Cash inflow from selling land is ₹5,00,000. Cash outflow for purchasing machinery is ₹8,00,000. Dividend received is an operating activity if it''s from trade investments, but typically considered investing if from strategic investments. Assuming it''s investing here, the net is ₹5,00,000 - ₹8,00,000 + ₹1,00,000 = ₹(2,00,000). However, dividends received are usually classified under operating activities if the company is in the business of investing, or investing activities otherwise. For standard classification, sale of land and purchase of machinery are investing. Net = ₹5,00,000 - ₹8,00,000 = ₹(3,00,000). Let''s re-evaluate the dividend. If the company''s primary business is not investing, dividend received is often treated as investing. So, ₹5,00,000 (inflow) - ₹8,00,000 (outflow) + ₹1,00,000 (inflow) = ₹(2,00,000). Correcting the assumption: Dividends received are generally investing activities unless the entity is a financial institution. So, ₹5,00,000 (sale of land) - ₹8,00,000 (purchase of machinery) + ₹1,00,000 (dividend received) = ₹(2,00,000).',
    'seed_rbse_commerce_deepen_accountancy_v1',
    true,
    'rbse',
    'ncert_aligned',
    'investing_activities',
    NULL,
    'commerce',
    'mcq'
  ),
