    'Reconstitution - Admission',
    'capital_adjustment',
    'hard',
    'P and Q are partners with capitals of Rs. 1,50,000 and Rs. 1,00,000 respectively. They admit R for 1/3rd share. R brings proportionate capital. The adjusted capitals of P and Q after all revaluations and reserve distributions are Rs. 1,60,000 and Rs. 1,10,000 respectively. What amount of capital should R bring?',
    '["Rs. 1,35,000","Rs. 90,000","Rs. 1,00,000","Rs. 85,000"]'::jsonb,
    1,
    'Combined adjusted capital of old partners (P+Q) = Rs. 1,60,000 + Rs. 1,10,000 = Rs. 2,70,000.
Remaining share of profit for P and Q = 1 - R''s share = 1 - 1/3 = 2/3.
If Rs. 2,70,000 represents 2/3rd of the total capital of the new firm, then the total capital of the new firm = Rs. 2,70,000 * (3/2) = Rs. 4,05,000.
R''s proportionate capital = Total Capital * R''s share = Rs. 4,05,000 * (1/3) = Rs. 1,35,000. 
Let''s re-check the options and my calculation. 
If the options are correct, then there might be a different interpretation of ''proportionate capital''. 
Let''s assume the total capital of the firm is based on the combined adjusted capital of old partners. 
Combined adjusted capital of P and Q = Rs. 2,70,000. This capital corresponds to their share of profit, which is 2/3.
So, if 2/3 share = Rs. 2,70,000, then 1/3 share = Rs. 2,70,000 / 2 = Rs. 1,35,000. This is the capital R should bring. 
Option A is Rs. 1,35,000. This matches my calculation. The question is well-posed and the options are correct. 
My previous check was correct, and the option is available.',
