    'hard',
    'A, B, and C are partners sharing profits in the ratio of 3:2:1. B retires and his amount due of ₹1,80,000 is transferred to his loan account. The loan is to be paid in three equal annual installments together with interest @ 12% p.a. on the outstanding balance. What will be the amount of the first installment (including interest)?',
