    0,
    'First, interest for the first year = ₹1,80,000 × 12% = ₹21,600. Amount due at end of year = ₹1,80,000 + ₹21,600 = ₹2,01,600. For three equal annual installments, the installment amount is calculated using the formula: Installment = P × r × (1+r)^n / [(1+r)^n – 1], where P = ₹1,80,000, r = 0.12, n = 3. (1+r)^n = 1.12^3 = 1.404928. Installment = 1,80,000 × 0.12 × 1.404928 / (1.404928 – 1) = ₹74,943 (approx). Hence the first installment includes interest and principal and equals ₹74,943.',
    'seed_rbse_commerce_deepen_accountancy_v1',
    true,
    'rbse',
    'ncert_aligned',
    'payment_to_retiring_partner_loan',
